{"version":3,"file":"static/css/3075.946e618d.chunk.css","mappings":"AAIA,MACE,oBAAqB,CACrB,yBAA0B,CAC1B,0BAA2B,CAC3B,iBAAkB,CAClB,mBAAoB,CACpB,mBAAoB,CACpB,eAAgB,CAChB,cAAe,CACf,iBAAkB,CAClB,kBAAmB,CACnB,mBAAoB,CACpB,gBACF,CAGA,SACE,eAAgC,CAAhC,8BAAgC,CAChC,wBAA2C,CAA3C,yCAA2C,CAC3C,kBAAqC,CAArC,mCAAqC,CACrC,YACF,CAEA,gBACE,6BAAiD,CAAjD,+CACF,CAEA,iBACE,6BAAgD,CAAhD,8CACF,CAEA,cACE,6BAA8C,CAA9C,4CACF,CAGA,SAGE,+BAAkD,CAAlD,gDAAkD,CAFlD,YAAa,CACb,OAAQ,CAER,kBACF,CAEA,QAKE,gBAAuB,CAEvB,WAAoC,CAApC,6BAAoC,CAHpC,aAA+B,CAA/B,6BAA+B,CAK/B,cAAe,CAPf,cAAe,CACf,eAAgB,CAKhB,kBAAmB,CAPnB,iBAAkB,CASlB,qCAAyC,CACzC,kBACF,CAMA,6BAHE,aAAiC,CAAjC,+BAOF,CAJA,eAEE,2BAA+C,CAA/C,6CAA+C,CAC/C,eACF,CAGA,UAGE,mBAAoB,CAFpB,oBAAqB,CAGrB,cAAe,CACf,eAAgB,CAEhB,oBAAsB,CALtB,gBAAiB,CAIjB,wBAEF,CAEA,oBACE,kBAA4C,CAA5C,0CAA4C,CAC5C,aAAsC,CAAtC,oCACF,CAEA,kBACE,kBAAmB,CACnB,aACF,CAEA,mBACE,kBAAmB,CACnB,aACF,CAEA,oBACE,kBAAmB,CACnB,aACF,CAEA,oBACE,kBAAmB,CACnB,aACF,CAOA,4CACE,kBAAmB,CACnB,aACF,CAGA,gBAEE,kBAAmB,CAGnB,kBAAsC,CAAtC,oCAAsC,CAEtC,WAAY,CACZ,iBAAkB,CAFlB,UAAW,CAKX,cAAe,CAVf,mBAAoB,CAQpB,cAAe,CACf,eAAgB,CAPhB,OAAQ,CACR,gBAAiB,CAQjB,qCACF,CAEA,sBACE,kBAA2C,CAA3C,yCACF,CAEA,yBAEE,kBAAmB,CADnB,WAEF,CAEA,gBAEE,kBAAmB,CAGnB,gBAAuB,CAEvB,0BAA8C,CAA9C,4CAA8C,CAC9C,iBAAkB,CAFlB,aAAiC,CAAjC,+BAAiC,CAKjC,cAAe,CAVf,mBAAoB,CAQpB,cAAe,CACf,eAAgB,CAPhB,OAAQ,CACR,gBAAiB,CAQjB,mCACF,CAEA,sBACE,kBAA4C,CAA5C,0CACF,CAEA,eAEE,kBAAmB,CAGnB,gBAAuB,CAEvB,0BAA6C,CAA7C,2CAA6C,CAC7C,iBAAkB,CAFlB,aAAgC,CAAhC,8BAAgC,CAKhC,cAAe,CAVf,mBAAoB,CAQpB,cAAe,CACf,eAAgB,CAPhB,OAAQ,CACR,gBAAiB,CAQjB,mCACF,CAEA,qBACE,kBACF,CAEA,gBAEE,kBAAmB,CAGnB,gBAAuB,CAEvB,0BAA6C,CAA7C,2CAA6C,CAC7C,iBAAkB,CAFlB,aAAc,CAKd,cAAe,CAVf,mBAAoB,CAQpB,cAAe,CACf,eAAgB,CAPhB,OAAQ,CACR,gBAAiB,CAQjB,mCACF,CAEA,sBACE,kBACF,CAEA,aAEE,kBAAmB,CAGnB,kBAAmC,CAAnC,iCAAmC,CAEnC,WAAY,CACZ,iBAAkB,CAFlB,UAAW,CAKX,cAAe,CAVf,mBAAoB,CAQpB,cAAe,CACf,eAAgB,CAPhB,OAAQ,CACR,gBAAiB,CAQjB,qCACF,CAEA,mBACE,kBACF,CAGA,cAGE,aAAS,CAFT,YAAa,CAEb,QAAS,CADT,mCAAqC,CAErC,gBAAiB,CACjB,eAAgB,CAChB,iBACF,CAEA,aACE,YAAa,CACb,qBAAsB,CACtB,OACF,CAEA,mBAGE,aAA+B,CAA/B,6BAA+B,CAF/B,cAAe,CACf,eAAgB,CAGhB,oBAAsB,CACtB,iBAAkB,CAFlB,wBAGF,CAEA,cAEE,kBAAiC,CAAjC,+BAAiC,CACjC,0BAA6C,CAA7C,2CAA6C,CAC7C,iBAAkB,CAGlB,aAA8B,CAA9B,4BAA8B,CAC9B,cAAe,CAHf,cAAe,CACf,eAAgB,CALhB,gBAAiB,CASjB,iBAAkB,CADlB,uDAEF,CAEA,oBAEE,aAAiC,CAAjC,+BACF,CAEA,2CAJE,oBAAwC,CAAxC,sCASF,CALA,uBACE,kBAAsC,CAAtC,oCAAsC,CAEtC,UAAW,CACX,eACF,CAEA,uBAEE,kBAAmB,CADnB,WAAa,CAEb,mBACF,CAGA,cAGE,aAAS,CAFT,YAAa,CAEb,QAAS,CADT,mCAEF,CAEA,cACE,eAAgC,CAAhC,8BAAgC,CAChC,wBAA2C,CAA3C,yCAA2C,CAC3C,kBAAqC,CAArC,mCAAqC,CAErC,YAAa,CACb,qBAAsB,CACtB,OAAQ,CAHR,iBAIF,CAEA,eAGE,aAA+B,CAA/B,6BAA+B,CAF/B,cAAe,CACf,eAAgB,CAGhB,oBAAsB,CADtB,wBAEF,CAEA,eAGE,aAA8B,CAA9B,4BAA8B,CAF9B,cAAe,CACf,eAAgB,CAEhB,eACF,CAGA,eAGE,kBAAmB,CAMnB,eAAgC,CAAhC,8BAAgC,CAFhC,0BAA6C,CAA7C,2CAA6C,CAC7C,iBAAkB,CAElB,cAAe,CARf,mBAAoB,CAIpB,WAAY,CAFZ,sBAAuB,CAHvB,iBAAkB,CAUlB,0CAA8C,CAN9C,UAOF,CAEA,qBACE,kBAA4C,CAA5C,0CAA4C,CAC5C,oBAAwC,CAAxC,sCACF,CAEA,mBAGE,aAA8B,CAA9B,4BAA8B,CAD9B,WAAY,CADZ,UAGF,CAEA,gBAaE,kBAAmB,CANnB,kBAAqC,CAArC,mCAAqC,CASrC,qBAAsB,CAPtB,mBAAoB,CADpB,UAAW,CAIX,YAAa,CAFb,cAAe,CACf,eAAgB,CANhB,WAAY,CASZ,sBAAuB,CACvB,aAAc,CAXd,cAAe,CAEf,aAAc,CALd,iBAAkB,CAElB,UAAW,CADX,QAeF,CAQA,mBACE,uBAAwB,CACxB,yBAA0B,CAC1B,wBAAyB,CACzB,uBAAwB,CACxB,uBAAwB,CACxB,yBAA0B,CAC1B,4BAA6B,CAC7B,kCAAmC,CAMnC,kCAAmC,CACnC,uCAAwC,CACxC,kBAAmB,CACnB,gCAA8C,CAE9C,eAAgB,CAThB,iBAAkB,CAElB,OAAQ,CADR,oBAAqB,CAErB,WAAY,CAKZ,WAEF,CAEA,0BAEE,kBAAmB,CAInB,kCAAmC,CACnC,8CAA+C,CAN/C,YAAa,CAGb,QAAS,CADT,6BAA8B,CAE9B,iBAGF,CAEA,6BAIE,2BAA4B,CAF5B,cAAe,CACf,eAAgB,CAFhB,QAIF,CAEA,iCAIE,eAAgB,CAChB,WAAY,CAFZ,4BAA6B,CAG7B,cAAe,CALf,cAAe,CACf,eAAgB,CAKhB,SAAU,CACV,kBACF,CAEA,uCACE,yBACF,CAEA,eACE,gBAAiB,CACjB,eAEF,CAEA,8BAHE,kCAUF,CAPA,eAIE,8CAA+C,CAC/C,cAAe,CAHf,2BAA4B,CAD5B,iBAAkB,CAKlB,0BACF,CAEA,0BACE,kBACF,CAEA,qBACE,kBACF,CAIA,sBACE,oCACF,CAEA,6BAOE,iCAAkC,CAFlC,QAAS,CAJT,UAAW,CAEX,MAAO,CADP,iBAAkB,CAElB,KAAM,CAEN,SAEF,CAEA,4BACE,0CACF,CAEA,qBAGE,2BAA4B,CAF5B,gBAAiB,CACjB,eAAgB,CAEhB,gBAAiB,CACjB,iBACF,CAEA,2CACE,eACF,CAEA,uBAEE,0BAA2B,CAD3B,gBAAiB,CAGjB,gBAAiB,CADjB,iBAEF,CAEA,oBAGE,0BAA2B,CAF3B,cAAe,CACf,eAEF,CAEA,gBAKE,kCAAmC,CADnC,0BAA2B,CAD3B,cAAe,CAFf,iBAAkB,CAClB,iBAIF,CAGA,sBAGE,aAAS,CAFT,YAAa,CAEb,QAAS,CADT,mCAEF,CAGA,gBACE,kBAAiC,CAAjC,+BAAiC,CACjC,wBAA2C,CAA3C,yCAA2C,CAC3C,iBAAkB,CAGlB,aAA8B,CAA9B,4BAA8B,CAD9B,cAAe,CAEf,eAAgB,CAHhB,iBAIF,CAEA,sBACE,aAA+B,CAA/B,6BAA+B,CAC/B,iBACF,CAGA,cAGE,aAAiC,CAAjC,+BAAiC,CAFjC,cAAe,CACf,eAAgB,CAEhB,qBACF,CAGA,yBACE,cACE,mCACF,CAEA,sBACE,yBACF,CAEA,cACE,mCACF,CAEA,mBAEE,WAAY,CADZ,WAEF,CACF","sources":["app/pages/Counselling/Counselling.css"],"sourcesContent":["/* ── Counselling Module Styles ── */\n/* Uses --sp-* CSS variables defined in StudentPortal.css */\n/* Overrides/fallbacks for Counselling-specific green theme */\n\n:root {\n  --sp-primary: #0C6B5A;\n  --sp-primary-dark: #084A3E;\n  --sp-primary-light: #E0F2EE;\n  --sp-info: #3B82F6;\n  --sp-accent: #F59E0B;\n  --sp-danger: #EF4444;\n  --sp-bg: #F2F7F5;\n  --sp-card: #fff;\n  --sp-text: #1A2B28;\n  --sp-muted: #5C7A72;\n  --sp-border: #D1E5DF;\n  --sp-radius: 12px;\n}\n\n/* ── Card ── */\n.cl-card {\n  background: var(--sp-card, #fff);\n  border: 1px solid var(--sp-border, #D1E5DF);\n  border-radius: var(--sp-radius, 12px);\n  padding: 20px;\n}\n\n.cl-card-accent {\n  border-left: 4px solid var(--sp-primary, #0C6B5A);\n}\n\n.cl-card-warning {\n  border-left: 4px solid var(--sp-accent, #F59E0B);\n}\n\n.cl-card-info {\n  border-left: 4px solid var(--sp-info, #3B82F6);\n}\n\n/* ── Tabs ── */\n.cl-tabs {\n  display: flex;\n  gap: 4px;\n  border-bottom: 2px solid var(--sp-border, #D1E5DF);\n  margin-bottom: 20px;\n}\n\n.cl-tab {\n  padding: 10px 18px;\n  font-size: 14px;\n  font-weight: 500;\n  color: var(--sp-muted, #5C7A72);\n  background: transparent;\n  border: none;\n  border-bottom: 2px solid transparent;\n  margin-bottom: -2px;\n  cursor: pointer;\n  transition: color 0.2s, border-color 0.2s;\n  white-space: nowrap;\n}\n\n.cl-tab:hover {\n  color: var(--sp-primary, #0C6B5A);\n}\n\n.cl-tab.active {\n  color: var(--sp-primary, #0C6B5A);\n  border-bottom-color: var(--sp-primary, #0C6B5A);\n  font-weight: 600;\n}\n\n/* ── Badge ── */\n.cl-badge {\n  display: inline-block;\n  padding: 3px 10px;\n  border-radius: 999px;\n  font-size: 12px;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.03em;\n}\n\n.cl-badge-confirmed {\n  background: var(--sp-primary-light, #E0F2EE);\n  color: var(--sp-primary-dark, #084A3E);\n}\n\n.cl-badge-pending {\n  background: #FEF3C7;\n  color: #92400E;\n}\n\n.cl-badge-assigned {\n  background: #DBEAFE;\n  color: #1E40AF;\n}\n\n.cl-badge-completed {\n  background: #D1FAE5;\n  color: #065F46;\n}\n\n.cl-badge-cancelled {\n  background: #FEE2E2;\n  color: #991B1B;\n}\n\n.cl-badge-rescheduled {\n  background: #FEF3C7;\n  color: #92400E;\n}\n\n.cl-badge-needs-notes {\n  background: #FEF3C7;\n  color: #92400E;\n}\n\n/* ── Buttons ── */\n.cl-btn-primary {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 8px 18px;\n  background: var(--sp-primary, #0C6B5A);\n  color: #fff;\n  border: none;\n  border-radius: 8px;\n  font-size: 14px;\n  font-weight: 600;\n  cursor: pointer;\n  transition: background 0.2s, opacity 0.2s;\n}\n\n.cl-btn-primary:hover {\n  background: var(--sp-primary-dark, #084A3E);\n}\n\n.cl-btn-primary:disabled {\n  opacity: 0.55;\n  cursor: not-allowed;\n}\n\n.cl-btn-outline {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 8px 18px;\n  background: transparent;\n  color: var(--sp-primary, #0C6B5A);\n  border: 1.5px solid var(--sp-primary, #0C6B5A);\n  border-radius: 8px;\n  font-size: 14px;\n  font-weight: 600;\n  cursor: pointer;\n  transition: background 0.2s, color 0.2s;\n}\n\n.cl-btn-outline:hover {\n  background: var(--sp-primary-light, #E0F2EE);\n}\n\n.cl-btn-danger {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 8px 18px;\n  background: transparent;\n  color: var(--sp-danger, #EF4444);\n  border: 1.5px solid var(--sp-danger, #EF4444);\n  border-radius: 8px;\n  font-size: 14px;\n  font-weight: 600;\n  cursor: pointer;\n  transition: background 0.2s, color 0.2s;\n}\n\n.cl-btn-danger:hover {\n  background: #FEE2E2;\n}\n\n.cl-btn-warning {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 8px 18px;\n  background: transparent;\n  color: #92400E;\n  border: 1.5px solid var(--sp-accent, #F59E0B);\n  border-radius: 8px;\n  font-size: 14px;\n  font-weight: 600;\n  cursor: pointer;\n  transition: background 0.2s, color 0.2s;\n}\n\n.cl-btn-warning:hover {\n  background: #FEF3C7;\n}\n\n.cl-btn-blue {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 8px 18px;\n  background: var(--sp-info, #3B82F6);\n  color: #fff;\n  border: none;\n  border-radius: 8px;\n  font-size: 14px;\n  font-weight: 600;\n  cursor: pointer;\n  transition: background 0.2s, opacity 0.2s;\n}\n\n.cl-btn-blue:hover {\n  background: #2563EB;\n}\n\n/* ── Slot Grid ── */\n.cl-slot-grid {\n  display: grid;\n  grid-template-columns: repeat(6, 1fr);\n  gap: 12px;\n  max-height: 450px;\n  overflow-y: auto;\n  padding-right: 4px;\n}\n\n.cl-slot-day {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\n.cl-slot-day-label {\n  font-size: 12px;\n  font-weight: 700;\n  color: var(--sp-muted, #5C7A72);\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n  margin-bottom: 4px;\n}\n\n.cl-slot-item {\n  padding: 8px 10px;\n  background: var(--sp-bg, #F2F7F5);\n  border: 1.5px solid var(--sp-border, #D1E5DF);\n  border-radius: 8px;\n  font-size: 13px;\n  font-weight: 500;\n  color: var(--sp-text, #1A2B28);\n  cursor: pointer;\n  transition: background 0.15s, border-color 0.15s, color 0.15s;\n  text-align: center;\n}\n\n.cl-slot-item:hover {\n  border-color: var(--sp-primary, #0C6B5A);\n  color: var(--sp-primary, #0C6B5A);\n}\n\n.cl-slot-item.selected {\n  background: var(--sp-primary, #0C6B5A);\n  border-color: var(--sp-primary, #0C6B5A);\n  color: #fff;\n  font-weight: 600;\n}\n\n.cl-slot-item.disabled {\n  opacity: 0.45;\n  cursor: not-allowed;\n  pointer-events: none;\n}\n\n/* ── Stats Bar ── */\n.cl-stats-bar {\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  gap: 16px;\n}\n\n.cl-stat-item {\n  background: var(--sp-card, #fff);\n  border: 1px solid var(--sp-border, #D1E5DF);\n  border-radius: var(--sp-radius, 12px);\n  padding: 16px 18px;\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n\n.cl-stat-label {\n  font-size: 12px;\n  font-weight: 500;\n  color: var(--sp-muted, #5C7A72);\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n}\n\n.cl-stat-value {\n  font-size: 26px;\n  font-weight: 700;\n  color: var(--sp-text, #1A2B28);\n  line-height: 1.1;\n}\n\n/* ── Notification Bell ── */\n.cl-notif-bell {\n  position: relative;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 40px;\n  height: 40px;\n  border: 1.5px solid var(--sp-border, #D1E5DF);\n  border-radius: 50%;\n  background: var(--sp-card, #fff);\n  cursor: pointer;\n  transition: background 0.2s, border-color 0.2s;\n}\n\n.cl-notif-bell:hover {\n  background: var(--sp-primary-light, #E0F2EE);\n  border-color: var(--sp-primary, #0C6B5A);\n}\n\n.cl-notif-bell svg {\n  width: 20px;\n  height: 20px;\n  color: var(--sp-text, #1A2B28);\n}\n\n.cl-notif-badge {\n  position: absolute;\n  top: -4px;\n  right: -4px;\n  min-width: 18px;\n  height: 18px;\n  padding: 0 4px;\n  background: var(--sp-danger, #EF4444);\n  color: #fff;\n  border-radius: 999px;\n  font-size: 10px;\n  font-weight: 700;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  line-height: 1;\n  border: 2px solid #fff;\n}\n\n/* The dropdown owns its palette outright.\n   It renders inside several different shells (the student portal's `.sp-shell`,\n   the counsellor dashboard, the admin Metronic pages), and each redefines the\n   --sp-* family to its own theme — `.sp-shell` sets --sp-primary-light to a\n   saturated green, which made the unread background dark while the text stayed\n   dark. Fixed literals here so the panel reads the same everywhere. */\n.cl-notif-dropdown {\n  --cl-notif-surface: #fff;\n  --cl-notif-border: #E3E8EF;\n  --cl-notif-title: #1A2B28;\n  --cl-notif-body: #4B5A66;\n  --cl-notif-meta: #78889A;\n  --cl-notif-accent: #0C6B5A;\n  --cl-notif-unread-bg: #F1F9F6;\n  --cl-notif-unread-bg-hover: #E4F3EE;\n\n  position: absolute;\n  top: calc(100% + 8px);\n  right: 0;\n  width: 340px;\n  background: var(--cl-notif-surface);\n  border: 1px solid var(--cl-notif-border);\n  border-radius: 12px;\n  box-shadow: 0 10px 28px rgba(16, 32, 40, 0.16);\n  z-index: 200;\n  overflow: hidden;\n}\n\n.cl-notif-dropdown-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  padding: 14px 16px;\n  background: var(--cl-notif-surface);\n  border-bottom: 1px solid var(--cl-notif-border);\n}\n\n.cl-notif-dropdown-header h4 {\n  margin: 0;\n  font-size: 14px;\n  font-weight: 700;\n  color: var(--cl-notif-title);\n}\n\n.cl-notif-dropdown-header button {\n  font-size: 12px;\n  font-weight: 600;\n  color: var(--cl-notif-accent);\n  background: none;\n  border: none;\n  cursor: pointer;\n  padding: 0;\n  white-space: nowrap;\n}\n\n.cl-notif-dropdown-header button:hover {\n  text-decoration: underline;\n}\n\n.cl-notif-list {\n  max-height: 360px;\n  overflow-y: auto;\n  background: var(--cl-notif-surface);\n}\n\n.cl-notif-item {\n  position: relative;\n  padding: 12px 16px 12px 18px;\n  background: var(--cl-notif-surface);\n  border-bottom: 1px solid var(--cl-notif-border);\n  cursor: pointer;\n  transition: background 0.15s;\n}\n\n.cl-notif-item:last-child {\n  border-bottom: none;\n}\n\n.cl-notif-item:hover {\n  background: #F5F7FA;\n}\n\n/* Unread is marked by a pale tint plus a solid accent rail, so the cue survives\n   without ever putting dark text on a dark fill. */\n.cl-notif-item.unread {\n  background: var(--cl-notif-unread-bg);\n}\n\n.cl-notif-item.unread::before {\n  content: '';\n  position: absolute;\n  left: 0;\n  top: 0;\n  bottom: 0;\n  width: 3px;\n  background: var(--cl-notif-accent);\n}\n\n.cl-notif-item.unread:hover {\n  background: var(--cl-notif-unread-bg-hover);\n}\n\n.cl-notif-item-title {\n  font-size: 13.5px;\n  font-weight: 600;\n  color: var(--cl-notif-title);\n  line-height: 1.35;\n  margin-bottom: 3px;\n}\n\n.cl-notif-item.unread .cl-notif-item-title {\n  font-weight: 700;\n}\n\n.cl-notif-item-message {\n  font-size: 12.5px;\n  color: var(--cl-notif-body);\n  margin-bottom: 5px;\n  line-height: 1.45;\n}\n\n.cl-notif-item-time {\n  font-size: 11px;\n  font-weight: 500;\n  color: var(--cl-notif-meta);\n}\n\n.cl-notif-empty {\n  padding: 24px 16px;\n  text-align: center;\n  font-size: 13px;\n  color: var(--cl-notif-meta);\n  background: var(--cl-notif-surface);\n}\n\n/* ── Availability Grid ── */\n.cl-availability-grid {\n  display: grid;\n  grid-template-columns: repeat(2, 1fr);\n  gap: 16px;\n}\n\n/* ── Remarks Box ── */\n.cl-remarks-box {\n  background: var(--sp-bg, #F2F7F5);\n  border: 1px solid var(--sp-border, #D1E5DF);\n  border-radius: 8px;\n  padding: 14px 16px;\n  font-size: 14px;\n  color: var(--sp-text, #1A2B28);\n  line-height: 1.6;\n}\n\n.cl-remarks-box.empty {\n  color: var(--sp-muted, #5C7A72);\n  font-style: italic;\n}\n\n/* ── Countdown ── */\n.cl-countdown {\n  font-size: 28px;\n  font-weight: 700;\n  color: var(--sp-primary, #0C6B5A);\n  letter-spacing: -0.02em;\n}\n\n/* ── Responsive ── */\n@media (max-width: 768px) {\n  .cl-slot-grid {\n    grid-template-columns: repeat(2, 1fr);\n  }\n\n  .cl-availability-grid {\n    grid-template-columns: 1fr;\n  }\n\n  .cl-stats-bar {\n    grid-template-columns: repeat(2, 1fr);\n  }\n\n  .cl-notif-dropdown {\n    width: 280px;\n    right: -16px;\n  }\n}\n"],"names":[],"sourceRoot":""}
