{"version":3,"file":"static/css/4787.10066d9c.chunk.css","mappings":"AAIA,MACE,oBAAqB,CACrB,yBAA0B,CAC1B,0BAA2B,CAC3B,iBAAkB,CAClB,mBAAoB,CACpB,mBAAoB,CACpB,eAAgB,CAChB,cAAe,CACf,iBAAkB,CAClB,kBAAmB,CACnB,mBAAoB,CACpB,gBACF,CAGA,SACE,eAAgC,CAAhC,8BAAgC,CAChC,wBAA2C,CAA3C,yCAA2C,CAC3C,kBAAqC,CAArC,mCAAqC,CACrC,YACF,CAEA,gBACE,6BAAiD,CAAjD,+CACF,CAEA,iBACE,6BAAgD,CAAhD,8CACF,CAEA,cACE,6BAA8C,CAA9C,4CACF,CAGA,SAGE,+BAAkD,CAAlD,gDAAkD,CAFlD,YAAa,CACb,OAAQ,CAER,kBACF,CAEA,QAKE,gBAAuB,CAEvB,WAAoC,CAApC,6BAAoC,CAHpC,aAA+B,CAA/B,6BAA+B,CAK/B,cAAe,CAPf,cAAe,CACf,eAAgB,CAKhB,kBAAmB,CAPnB,iBAAkB,CASlB,qCAAyC,CACzC,kBACF,CAMA,6BAHE,aAAiC,CAAjC,+BAOF,CAJA,eAEE,2BAA+C,CAA/C,6CAA+C,CAC/C,eACF,CAGA,UAGE,mBAAoB,CAFpB,oBAAqB,CAGrB,cAAe,CACf,eAAgB,CAEhB,oBAAsB,CALtB,gBAAiB,CAIjB,wBAEF,CAEA,oBACE,kBAA4C,CAA5C,0CAA4C,CAC5C,aAAsC,CAAtC,oCACF,CAEA,kBACE,kBAAmB,CACnB,aACF,CAEA,mBACE,kBAAmB,CACnB,aACF,CAEA,oBACE,kBAAmB,CACnB,aACF,CAEA,oBACE,kBAAmB,CACnB,aACF,CAOA,4CACE,kBAAmB,CACnB,aACF,CAGA,gBAEE,kBAAmB,CAGnB,kBAAsC,CAAtC,oCAAsC,CAEtC,WAAY,CACZ,iBAAkB,CAFlB,UAAW,CAKX,cAAe,CAVf,mBAAoB,CAQpB,cAAe,CACf,eAAgB,CAPhB,OAAQ,CACR,gBAAiB,CAQjB,qCACF,CAEA,sBACE,kBAA2C,CAA3C,yCACF,CAEA,yBAEE,kBAAmB,CADnB,WAEF,CAEA,gBAEE,kBAAmB,CAGnB,gBAAuB,CAEvB,0BAA8C,CAA9C,4CAA8C,CAC9C,iBAAkB,CAFlB,aAAiC,CAAjC,+BAAiC,CAKjC,cAAe,CAVf,mBAAoB,CAQpB,cAAe,CACf,eAAgB,CAPhB,OAAQ,CACR,gBAAiB,CAQjB,mCACF,CAEA,sBACE,kBAA4C,CAA5C,0CACF,CAEA,eAEE,kBAAmB,CAGnB,gBAAuB,CAEvB,0BAA6C,CAA7C,2CAA6C,CAC7C,iBAAkB,CAFlB,aAAgC,CAAhC,8BAAgC,CAKhC,cAAe,CAVf,mBAAoB,CAQpB,cAAe,CACf,eAAgB,CAPhB,OAAQ,CACR,gBAAiB,CAQjB,mCACF,CAEA,qBACE,kBACF,CAEA,gBAEE,kBAAmB,CAGnB,gBAAuB,CAEvB,0BAA6C,CAA7C,2CAA6C,CAC7C,iBAAkB,CAFlB,aAAc,CAKd,cAAe,CAVf,mBAAoB,CAQpB,cAAe,CACf,eAAgB,CAPhB,OAAQ,CACR,gBAAiB,CAQjB,mCACF,CAEA,sBACE,kBACF,CAEA,aAEE,kBAAmB,CAGnB,kBAAmC,CAAnC,iCAAmC,CAEnC,WAAY,CACZ,iBAAkB,CAFlB,UAAW,CAKX,cAAe,CAVf,mBAAoB,CAQpB,cAAe,CACf,eAAgB,CAPhB,OAAQ,CACR,gBAAiB,CAQjB,qCACF,CAEA,mBACE,kBACF,CAGA,cAGE,aAAS,CAFT,YAAa,CAEb,QAAS,CADT,mCAAqC,CAErC,gBAAiB,CACjB,eAAgB,CAChB,iBACF,CAEA,aACE,YAAa,CACb,qBAAsB,CACtB,OACF,CAEA,mBAGE,aAA+B,CAA/B,6BAA+B,CAF/B,cAAe,CACf,eAAgB,CAGhB,oBAAsB,CACtB,iBAAkB,CAFlB,wBAGF,CAEA,cAEE,kBAAiC,CAAjC,+BAAiC,CACjC,0BAA6C,CAA7C,2CAA6C,CAC7C,iBAAkB,CAGlB,aAA8B,CAA9B,4BAA8B,CAC9B,cAAe,CAHf,cAAe,CACf,eAAgB,CALhB,gBAAiB,CASjB,iBAAkB,CADlB,uDAEF,CAEA,oBAEE,aAAiC,CAAjC,+BACF,CAEA,2CAJE,oBAAwC,CAAxC,sCASF,CALA,uBACE,kBAAsC,CAAtC,oCAAsC,CAEtC,UAAW,CACX,eACF,CAEA,uBAEE,kBAAmB,CADnB,WAAa,CAEb,mBACF,CAGA,cAGE,aAAS,CAFT,YAAa,CAEb,QAAS,CADT,mCAEF,CAEA,cACE,eAAgC,CAAhC,8BAAgC,CAChC,wBAA2C,CAA3C,yCAA2C,CAC3C,kBAAqC,CAArC,mCAAqC,CAErC,YAAa,CACb,qBAAsB,CACtB,OAAQ,CAHR,iBAIF,CAEA,eAGE,aAA+B,CAA/B,6BAA+B,CAF/B,cAAe,CACf,eAAgB,CAGhB,oBAAsB,CADtB,wBAEF,CAEA,eAGE,aAA8B,CAA9B,4BAA8B,CAF9B,cAAe,CACf,eAAgB,CAEhB,eACF,CAGA,eAGE,kBAAmB,CAMnB,eAAgC,CAAhC,8BAAgC,CAFhC,0BAA6C,CAA7C,2CAA6C,CAC7C,iBAAkB,CAElB,cAAe,CARf,mBAAoB,CAIpB,WAAY,CAFZ,sBAAuB,CAHvB,iBAAkB,CAUlB,0CAA8C,CAN9C,UAOF,CAEA,qBACE,kBAA4C,CAA5C,0CAA4C,CAC5C,oBAAwC,CAAxC,sCACF,CAEA,mBAGE,aAA8B,CAA9B,4BAA8B,CAD9B,WAAY,CADZ,UAGF,CAEA,gBAaE,kBAAmB,CANnB,kBAAqC,CAArC,mCAAqC,CASrC,qBAAsB,CAPtB,mBAAoB,CADpB,UAAW,CAIX,YAAa,CAFb,cAAe,CACf,eAAgB,CANhB,WAAY,CASZ,sBAAuB,CACvB,aAAc,CAXd,cAAe,CAEf,aAAc,CALd,iBAAkB,CAElB,UAAW,CADX,QAeF,CAQA,mBACE,uBAAwB,CACxB,yBAA0B,CAC1B,wBAAyB,CACzB,uBAAwB,CACxB,uBAAwB,CACxB,yBAA0B,CAC1B,4BAA6B,CAC7B,kCAAmC,CAMnC,kCAAmC,CACnC,uCAAwC,CACxC,kBAAmB,CACnB,gCAA8C,CAE9C,eAAgB,CAThB,iBAAkB,CAElB,OAAQ,CADR,oBAAqB,CAErB,WAAY,CAKZ,WAEF,CAEA,0BAEE,kBAAmB,CAInB,kCAAmC,CACnC,8CAA+C,CAN/C,YAAa,CAGb,QAAS,CADT,6BAA8B,CAE9B,iBAGF,CAEA,6BAIE,2BAA4B,CAF5B,cAAe,CACf,eAAgB,CAFhB,QAIF,CAEA,iCAIE,eAAgB,CAChB,WAAY,CAFZ,4BAA6B,CAG7B,cAAe,CALf,cAAe,CACf,eAAgB,CAKhB,SAAU,CACV,kBACF,CAEA,uCACE,yBACF,CAEA,eACE,gBAAiB,CACjB,eAEF,CAEA,8BAHE,kCAUF,CAPA,eAIE,8CAA+C,CAC/C,cAAe,CAHf,2BAA4B,CAD5B,iBAAkB,CAKlB,0BACF,CAEA,0BACE,kBACF,CAEA,qBACE,kBACF,CAIA,sBACE,oCACF,CAEA,6BAOE,iCAAkC,CAFlC,QAAS,CAJT,UAAW,CAEX,MAAO,CADP,iBAAkB,CAElB,KAAM,CAEN,SAEF,CAEA,4BACE,0CACF,CAEA,qBAGE,2BAA4B,CAF5B,gBAAiB,CACjB,eAAgB,CAEhB,gBAAiB,CACjB,iBACF,CAEA,2CACE,eACF,CAEA,uBAEE,0BAA2B,CAD3B,gBAAiB,CAGjB,gBAAiB,CADjB,iBAEF,CAEA,oBAGE,0BAA2B,CAF3B,cAAe,CACf,eAEF,CAEA,gBAKE,kCAAmC,CADnC,0BAA2B,CAD3B,cAAe,CAFf,iBAAkB,CAClB,iBAIF,CAGA,sBAGE,aAAS,CAFT,YAAa,CAEb,QAAS,CADT,mCAEF,CAGA,gBACE,kBAAiC,CAAjC,+BAAiC,CACjC,wBAA2C,CAA3C,yCAA2C,CAC3C,iBAAkB,CAGlB,aAA8B,CAA9B,4BAA8B,CAD9B,cAAe,CAEf,eAAgB,CAHhB,iBAIF,CAEA,sBACE,aAA+B,CAA/B,6BAA+B,CAC/B,iBACF,CAGA,cAGE,aAAiC,CAAjC,+BAAiC,CAFjC,cAAe,CACf,eAAgB,CAEhB,qBACF,CAGA,yBACE,cACE,mCACF,CAEA,sBACE,yBACF,CAEA,cACE,mCACF,CAEA,mBAEE,WAAY,CADZ,WAEF,CACF","sources":["app/pages/Counselling/Counselling.css"],"sourcesContent":["/* ── Counselling Module Styles ── */\r\n/* Uses --sp-* CSS variables defined in StudentPortal.css */\r\n/* Overrides/fallbacks for Counselling-specific green theme */\r\n\r\n:root {\r\n  --sp-primary: #0C6B5A;\r\n  --sp-primary-dark: #084A3E;\r\n  --sp-primary-light: #E0F2EE;\r\n  --sp-info: #3B82F6;\r\n  --sp-accent: #F59E0B;\r\n  --sp-danger: #EF4444;\r\n  --sp-bg: #F2F7F5;\r\n  --sp-card: #fff;\r\n  --sp-text: #1A2B28;\r\n  --sp-muted: #5C7A72;\r\n  --sp-border: #D1E5DF;\r\n  --sp-radius: 12px;\r\n}\r\n\r\n/* ── Card ── */\r\n.cl-card {\r\n  background: var(--sp-card, #fff);\r\n  border: 1px solid var(--sp-border, #D1E5DF);\r\n  border-radius: var(--sp-radius, 12px);\r\n  padding: 20px;\r\n}\r\n\r\n.cl-card-accent {\r\n  border-left: 4px solid var(--sp-primary, #0C6B5A);\r\n}\r\n\r\n.cl-card-warning {\r\n  border-left: 4px solid var(--sp-accent, #F59E0B);\r\n}\r\n\r\n.cl-card-info {\r\n  border-left: 4px solid var(--sp-info, #3B82F6);\r\n}\r\n\r\n/* ── Tabs ── */\r\n.cl-tabs {\r\n  display: flex;\r\n  gap: 4px;\r\n  border-bottom: 2px solid var(--sp-border, #D1E5DF);\r\n  margin-bottom: 20px;\r\n}\r\n\r\n.cl-tab {\r\n  padding: 10px 18px;\r\n  font-size: 14px;\r\n  font-weight: 500;\r\n  color: var(--sp-muted, #5C7A72);\r\n  background: transparent;\r\n  border: none;\r\n  border-bottom: 2px solid transparent;\r\n  margin-bottom: -2px;\r\n  cursor: pointer;\r\n  transition: color 0.2s, border-color 0.2s;\r\n  white-space: nowrap;\r\n}\r\n\r\n.cl-tab:hover {\r\n  color: var(--sp-primary, #0C6B5A);\r\n}\r\n\r\n.cl-tab.active {\r\n  color: var(--sp-primary, #0C6B5A);\r\n  border-bottom-color: var(--sp-primary, #0C6B5A);\r\n  font-weight: 600;\r\n}\r\n\r\n/* ── Badge ── */\r\n.cl-badge {\r\n  display: inline-block;\r\n  padding: 3px 10px;\r\n  border-radius: 999px;\r\n  font-size: 12px;\r\n  font-weight: 600;\r\n  text-transform: uppercase;\r\n  letter-spacing: 0.03em;\r\n}\r\n\r\n.cl-badge-confirmed {\r\n  background: var(--sp-primary-light, #E0F2EE);\r\n  color: var(--sp-primary-dark, #084A3E);\r\n}\r\n\r\n.cl-badge-pending {\r\n  background: #FEF3C7;\r\n  color: #92400E;\r\n}\r\n\r\n.cl-badge-assigned {\r\n  background: #DBEAFE;\r\n  color: #1E40AF;\r\n}\r\n\r\n.cl-badge-completed {\r\n  background: #D1FAE5;\r\n  color: #065F46;\r\n}\r\n\r\n.cl-badge-cancelled {\r\n  background: #FEE2E2;\r\n  color: #991B1B;\r\n}\r\n\r\n.cl-badge-rescheduled {\r\n  background: #FEF3C7;\r\n  color: #92400E;\r\n}\r\n\r\n.cl-badge-needs-notes {\r\n  background: #FEF3C7;\r\n  color: #92400E;\r\n}\r\n\r\n/* ── Buttons ── */\r\n.cl-btn-primary {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 6px;\r\n  padding: 8px 18px;\r\n  background: var(--sp-primary, #0C6B5A);\r\n  color: #fff;\r\n  border: none;\r\n  border-radius: 8px;\r\n  font-size: 14px;\r\n  font-weight: 600;\r\n  cursor: pointer;\r\n  transition: background 0.2s, opacity 0.2s;\r\n}\r\n\r\n.cl-btn-primary:hover {\r\n  background: var(--sp-primary-dark, #084A3E);\r\n}\r\n\r\n.cl-btn-primary:disabled {\r\n  opacity: 0.55;\r\n  cursor: not-allowed;\r\n}\r\n\r\n.cl-btn-outline {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 6px;\r\n  padding: 8px 18px;\r\n  background: transparent;\r\n  color: var(--sp-primary, #0C6B5A);\r\n  border: 1.5px solid var(--sp-primary, #0C6B5A);\r\n  border-radius: 8px;\r\n  font-size: 14px;\r\n  font-weight: 600;\r\n  cursor: pointer;\r\n  transition: background 0.2s, color 0.2s;\r\n}\r\n\r\n.cl-btn-outline:hover {\r\n  background: var(--sp-primary-light, #E0F2EE);\r\n}\r\n\r\n.cl-btn-danger {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 6px;\r\n  padding: 8px 18px;\r\n  background: transparent;\r\n  color: var(--sp-danger, #EF4444);\r\n  border: 1.5px solid var(--sp-danger, #EF4444);\r\n  border-radius: 8px;\r\n  font-size: 14px;\r\n  font-weight: 600;\r\n  cursor: pointer;\r\n  transition: background 0.2s, color 0.2s;\r\n}\r\n\r\n.cl-btn-danger:hover {\r\n  background: #FEE2E2;\r\n}\r\n\r\n.cl-btn-warning {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 6px;\r\n  padding: 8px 18px;\r\n  background: transparent;\r\n  color: #92400E;\r\n  border: 1.5px solid var(--sp-accent, #F59E0B);\r\n  border-radius: 8px;\r\n  font-size: 14px;\r\n  font-weight: 600;\r\n  cursor: pointer;\r\n  transition: background 0.2s, color 0.2s;\r\n}\r\n\r\n.cl-btn-warning:hover {\r\n  background: #FEF3C7;\r\n}\r\n\r\n.cl-btn-blue {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 6px;\r\n  padding: 8px 18px;\r\n  background: var(--sp-info, #3B82F6);\r\n  color: #fff;\r\n  border: none;\r\n  border-radius: 8px;\r\n  font-size: 14px;\r\n  font-weight: 600;\r\n  cursor: pointer;\r\n  transition: background 0.2s, opacity 0.2s;\r\n}\r\n\r\n.cl-btn-blue:hover {\r\n  background: #2563EB;\r\n}\r\n\r\n/* ── Slot Grid ── */\r\n.cl-slot-grid {\r\n  display: grid;\r\n  grid-template-columns: repeat(6, 1fr);\r\n  gap: 12px;\r\n  max-height: 450px;\r\n  overflow-y: auto;\r\n  padding-right: 4px;\r\n}\r\n\r\n.cl-slot-day {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 6px;\r\n}\r\n\r\n.cl-slot-day-label {\r\n  font-size: 12px;\r\n  font-weight: 700;\r\n  color: var(--sp-muted, #5C7A72);\r\n  text-transform: uppercase;\r\n  letter-spacing: 0.05em;\r\n  margin-bottom: 4px;\r\n}\r\n\r\n.cl-slot-item {\r\n  padding: 8px 10px;\r\n  background: var(--sp-bg, #F2F7F5);\r\n  border: 1.5px solid var(--sp-border, #D1E5DF);\r\n  border-radius: 8px;\r\n  font-size: 13px;\r\n  font-weight: 500;\r\n  color: var(--sp-text, #1A2B28);\r\n  cursor: pointer;\r\n  transition: background 0.15s, border-color 0.15s, color 0.15s;\r\n  text-align: center;\r\n}\r\n\r\n.cl-slot-item:hover {\r\n  border-color: var(--sp-primary, #0C6B5A);\r\n  color: var(--sp-primary, #0C6B5A);\r\n}\r\n\r\n.cl-slot-item.selected {\r\n  background: var(--sp-primary, #0C6B5A);\r\n  border-color: var(--sp-primary, #0C6B5A);\r\n  color: #fff;\r\n  font-weight: 600;\r\n}\r\n\r\n.cl-slot-item.disabled {\r\n  opacity: 0.45;\r\n  cursor: not-allowed;\r\n  pointer-events: none;\r\n}\r\n\r\n/* ── Stats Bar ── */\r\n.cl-stats-bar {\r\n  display: grid;\r\n  grid-template-columns: repeat(4, 1fr);\r\n  gap: 16px;\r\n}\r\n\r\n.cl-stat-item {\r\n  background: var(--sp-card, #fff);\r\n  border: 1px solid var(--sp-border, #D1E5DF);\r\n  border-radius: var(--sp-radius, 12px);\r\n  padding: 16px 18px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 4px;\r\n}\r\n\r\n.cl-stat-label {\r\n  font-size: 12px;\r\n  font-weight: 500;\r\n  color: var(--sp-muted, #5C7A72);\r\n  text-transform: uppercase;\r\n  letter-spacing: 0.04em;\r\n}\r\n\r\n.cl-stat-value {\r\n  font-size: 26px;\r\n  font-weight: 700;\r\n  color: var(--sp-text, #1A2B28);\r\n  line-height: 1.1;\r\n}\r\n\r\n/* ── Notification Bell ── */\r\n.cl-notif-bell {\r\n  position: relative;\r\n  display: inline-flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  width: 40px;\r\n  height: 40px;\r\n  border: 1.5px solid var(--sp-border, #D1E5DF);\r\n  border-radius: 50%;\r\n  background: var(--sp-card, #fff);\r\n  cursor: pointer;\r\n  transition: background 0.2s, border-color 0.2s;\r\n}\r\n\r\n.cl-notif-bell:hover {\r\n  background: var(--sp-primary-light, #E0F2EE);\r\n  border-color: var(--sp-primary, #0C6B5A);\r\n}\r\n\r\n.cl-notif-bell svg {\r\n  width: 20px;\r\n  height: 20px;\r\n  color: var(--sp-text, #1A2B28);\r\n}\r\n\r\n.cl-notif-badge {\r\n  position: absolute;\r\n  top: -4px;\r\n  right: -4px;\r\n  min-width: 18px;\r\n  height: 18px;\r\n  padding: 0 4px;\r\n  background: var(--sp-danger, #EF4444);\r\n  color: #fff;\r\n  border-radius: 999px;\r\n  font-size: 10px;\r\n  font-weight: 700;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  line-height: 1;\r\n  border: 2px solid #fff;\r\n}\r\n\r\n/* The dropdown owns its palette outright.\r\n   It renders inside several different shells (the student portal's `.sp-shell`,\r\n   the counsellor dashboard, the admin Metronic pages), and each redefines the\r\n   --sp-* family to its own theme — `.sp-shell` sets --sp-primary-light to a\r\n   saturated green, which made the unread background dark while the text stayed\r\n   dark. Fixed literals here so the panel reads the same everywhere. */\r\n.cl-notif-dropdown {\r\n  --cl-notif-surface: #fff;\r\n  --cl-notif-border: #E3E8EF;\r\n  --cl-notif-title: #1A2B28;\r\n  --cl-notif-body: #4B5A66;\r\n  --cl-notif-meta: #78889A;\r\n  --cl-notif-accent: #0C6B5A;\r\n  --cl-notif-unread-bg: #F1F9F6;\r\n  --cl-notif-unread-bg-hover: #E4F3EE;\r\n\r\n  position: absolute;\r\n  top: calc(100% + 8px);\r\n  right: 0;\r\n  width: 340px;\r\n  background: var(--cl-notif-surface);\r\n  border: 1px solid var(--cl-notif-border);\r\n  border-radius: 12px;\r\n  box-shadow: 0 10px 28px rgba(16, 32, 40, 0.16);\r\n  z-index: 200;\r\n  overflow: hidden;\r\n}\r\n\r\n.cl-notif-dropdown-header {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  gap: 12px;\r\n  padding: 14px 16px;\r\n  background: var(--cl-notif-surface);\r\n  border-bottom: 1px solid var(--cl-notif-border);\r\n}\r\n\r\n.cl-notif-dropdown-header h4 {\r\n  margin: 0;\r\n  font-size: 14px;\r\n  font-weight: 700;\r\n  color: var(--cl-notif-title);\r\n}\r\n\r\n.cl-notif-dropdown-header button {\r\n  font-size: 12px;\r\n  font-weight: 600;\r\n  color: var(--cl-notif-accent);\r\n  background: none;\r\n  border: none;\r\n  cursor: pointer;\r\n  padding: 0;\r\n  white-space: nowrap;\r\n}\r\n\r\n.cl-notif-dropdown-header button:hover {\r\n  text-decoration: underline;\r\n}\r\n\r\n.cl-notif-list {\r\n  max-height: 360px;\r\n  overflow-y: auto;\r\n  background: var(--cl-notif-surface);\r\n}\r\n\r\n.cl-notif-item {\r\n  position: relative;\r\n  padding: 12px 16px 12px 18px;\r\n  background: var(--cl-notif-surface);\r\n  border-bottom: 1px solid var(--cl-notif-border);\r\n  cursor: pointer;\r\n  transition: background 0.15s;\r\n}\r\n\r\n.cl-notif-item:last-child {\r\n  border-bottom: none;\r\n}\r\n\r\n.cl-notif-item:hover {\r\n  background: #F5F7FA;\r\n}\r\n\r\n/* Unread is marked by a pale tint plus a solid accent rail, so the cue survives\r\n   without ever putting dark text on a dark fill. */\r\n.cl-notif-item.unread {\r\n  background: var(--cl-notif-unread-bg);\r\n}\r\n\r\n.cl-notif-item.unread::before {\r\n  content: '';\r\n  position: absolute;\r\n  left: 0;\r\n  top: 0;\r\n  bottom: 0;\r\n  width: 3px;\r\n  background: var(--cl-notif-accent);\r\n}\r\n\r\n.cl-notif-item.unread:hover {\r\n  background: var(--cl-notif-unread-bg-hover);\r\n}\r\n\r\n.cl-notif-item-title {\r\n  font-size: 13.5px;\r\n  font-weight: 600;\r\n  color: var(--cl-notif-title);\r\n  line-height: 1.35;\r\n  margin-bottom: 3px;\r\n}\r\n\r\n.cl-notif-item.unread .cl-notif-item-title {\r\n  font-weight: 700;\r\n}\r\n\r\n.cl-notif-item-message {\r\n  font-size: 12.5px;\r\n  color: var(--cl-notif-body);\r\n  margin-bottom: 5px;\r\n  line-height: 1.45;\r\n}\r\n\r\n.cl-notif-item-time {\r\n  font-size: 11px;\r\n  font-weight: 500;\r\n  color: var(--cl-notif-meta);\r\n}\r\n\r\n.cl-notif-empty {\r\n  padding: 24px 16px;\r\n  text-align: center;\r\n  font-size: 13px;\r\n  color: var(--cl-notif-meta);\r\n  background: var(--cl-notif-surface);\r\n}\r\n\r\n/* ── Availability Grid ── */\r\n.cl-availability-grid {\r\n  display: grid;\r\n  grid-template-columns: repeat(2, 1fr);\r\n  gap: 16px;\r\n}\r\n\r\n/* ── Remarks Box ── */\r\n.cl-remarks-box {\r\n  background: var(--sp-bg, #F2F7F5);\r\n  border: 1px solid var(--sp-border, #D1E5DF);\r\n  border-radius: 8px;\r\n  padding: 14px 16px;\r\n  font-size: 14px;\r\n  color: var(--sp-text, #1A2B28);\r\n  line-height: 1.6;\r\n}\r\n\r\n.cl-remarks-box.empty {\r\n  color: var(--sp-muted, #5C7A72);\r\n  font-style: italic;\r\n}\r\n\r\n/* ── Countdown ── */\r\n.cl-countdown {\r\n  font-size: 28px;\r\n  font-weight: 700;\r\n  color: var(--sp-primary, #0C6B5A);\r\n  letter-spacing: -0.02em;\r\n}\r\n\r\n/* ── Responsive ── */\r\n@media (max-width: 768px) {\r\n  .cl-slot-grid {\r\n    grid-template-columns: repeat(2, 1fr);\r\n  }\r\n\r\n  .cl-availability-grid {\r\n    grid-template-columns: 1fr;\r\n  }\r\n\r\n  .cl-stats-bar {\r\n    grid-template-columns: repeat(2, 1fr);\r\n  }\r\n\r\n  .cl-notif-dropdown {\r\n    width: 280px;\r\n    right: -16px;\r\n  }\r\n}\r\n"],"names":[],"sourceRoot":""}
